//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			 HE_AlarmGeneral                                                                                                                                                                                                                                                                 
//	CREATOR:		 William Veim, Helgevold Elektro                                                                                                                                                                                                                                             
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0					31.03.2025		William Veim				Initial Release
//	1.0.1					29.04.2025		Ruben Byman				Added trigger input
//	1.0.2					16.05.2025		Ruben Byman				Added missing R_TRIGs
// 1.0.3					24.06.2025		Fredrik Bjerkenes 		Inp_Processvalue string increased from 4 to 25
// 1.0.4					24.06.2025		Fredrik Bjerkenes 		Alarm suppressed when return delay Q is True Sts suppressed is set to false
// 1.0.5					02.09.2025		William Veim	 			Rework alarm token (handle clear of alarm array)
// 1.0.6					04.09.2025		William Veim	 			Bugfix not reset alarm if analog alarm active
// 1.0.7					15.09.2025		William Veim	 			Editet priority from number to text
// 1.0.7					19.09.2025		William Veim	 			Bugfix find new token
// 1.0.8					18.11.2025		William Veim	 			Editet alarm control - from FOR loop, to check one alarm each cycle
// 1.0.9					13.03.2026		William Veim	 			New condition for reset alarm - "Not active AND state > 1" - Ensure SMS sending if low active time.
// 1.0.10				18.03.2026		William Veim	 			Improvement acknowledgement - Could be missed in spesific scenarioes
// 1.0.11				30.06.2026		William Veim	 			Bugfix alarm return send when function activated
//
//===============================================================================================================================
//
//		DESCRIPTION:
//		Alarm structure for one value/control structure/funkction. Each set of alarm includes data for sending 16 individual messages/alarms is structure 0-15
//		-Index 0-10 is used for state config data (ex "loop break', 'module fault' or input spesific data from digital value
//		-Index 11-14 is used for analog alarms ('critical low', 'low, 'high', 'critical high')
//		-Index 15 is used for test alarm
//
//==============================================================================================================================

(*************************************************************************
 *	ASSIGNS ALARM INDEX 
 *************************************************************************)
 
 //Execute once a lifetime (or if edited array size, or array has been cleared)
IF AlarmToken=-1 OR AlarmToken > DINT_TO_INT(UPPER_BOUND(Int_Alarm,1)) OR AlarmToken < DINT_TO_INT(LOWER_BOUND(Int_Alarm,1)) OR NOT Int_Alarm[AlarmToken].Cfg_InUse THEN
	FOR AlarmToken:=DINT_TO_INT(LOWER_BOUND(Int_Alarm,1)) TO DINT_TO_INT(UPPER_BOUND(Int_Alarm, 1)) DO 
		IF NOT Int_Alarm[AlarmToken].Cfg_InUse THEN
			Int_Alarm[AlarmToken].Cfg_InUse := TRUE;
			EXIT;
		END_IF;
	END_FOR;
END_IF;

(*************************************************************************
 *	ALARM INDEX CONTROL
 *************************************************************************)

Inc(AlarmIndex);
IF AlarmIndex>UPPER_BOUND(Inp_AlarmData, 1) THEN
	AlarmIndex:=DINT_TO_INT(LOWER_BOUND(Inp_AlarmData,1));
END_IF;

(*************************************************************************
 *	SUPRESS CONTROL
 *************************************************************************)
 
TON_SupressReturn(PT:=SecToTime(Ext_Alarm.Cfg_SupressDelayOff));

//Supress state
IF Inp_AlarmSupress THEN //Supress input active
	Ext_Alarm.Sts_Suppressed:=TRUE;
	Ext_Alarm.Sts_SuppressedDesc:=Inp_AlmSuppressDesc;
ELSIF Ext_Alarm.Sts_Suppressed AND NOT Inp_AlarmSupress THEN //Supressed and input not active
	TON_SupressReturn.In:=TRUE;
	IF TON_SupressReturn.Q THEN
		Ext_Alarm.Sts_Suppressed:=FALSE;
		Ext_Alarm.Sts_SuppressedDesc:='';
		TON_SupressReturn.In:=FALSE;
	END_IF;
END_IF;
 
(*************************************************************************
 *	ALARM TIMER
 *************************************************************************)
 
//ALARM CONTROL
//-----------------------
//Execution of one alarm each cycle (reduce cycle time)

//Timer Control
TON_AlarmTrig[AlarmIndex](In:=Inp_AlarmData[AlarmIndex].Alm_State AND Ext_Alarm.Cfg_OnOff AND NOT Ext_Alarm.Sts_Suppressed, PT:=SecToTime(Ext_Alarm.Cfg_AlarmActiveDelay));
TOF_AlarmReturn[AlarmIndex](In:=Inp_AlarmData[AlarmIndex].Alm_State AND Ext_Alarm.Cfg_OnOff AND NOT Ext_Alarm.Sts_Suppressed, PT:=SecToTime(Ext_Alarm.Cfg_AlarmReturnDelay));

//Alarm trigger
IF TON_AlarmTrig[AlarmIndex].Q AND Ext_Alarm.Cfg_OnOff AND NOT Ext_Alarm.Sts_Suppressed THEN
	Wrk_Alarm[AlarmIndex]:=TRUE;
//Alarm return
ELSIF (NOT TOF_AlarmReturn[AlarmIndex].Q) OR (NOT Ext_Alarm.Cfg_OnOff) OR (Ext_Alarm.Sts_Suppressed) THEN
	Wrk_Alarm[AlarmIndex]:=FALSE;
END_IF;
 
(*************************************************************************
 *	DATA CONTROL
 *************************************************************************)

//DATA TO INTERNAL STRUCTURE
//------------------------------------

//Fixed data
Int_Alarm[AlarmToken].Sts_Location :=									Inp_LocationData;
Int_Alarm[AlarmToken].Sts_Connected_Cabinet:=					Inp_Connected_Cabinet;
Int_Alarm[AlarmToken].Sts_Connected_Controller:=				Inp_Connected_Controller;
Int_Alarm[AlarmToken].Sts_Process_TAG:=								Inp_Process_TAG;
Int_Alarm[AlarmToken].Sts_Process_Value:=							Inp_Process_Value;
Int_Alarm[AlarmToken].Sts_Process_Desc:=							Inp_Process_Desc;
Int_Alarm[AlarmToken].Sts_SMS_OnlyDayTime:=					Ext_Alarm.Cfg_SMS_OnlyDayTime;

//Dynamic data
Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_Suffix:=			Inp_AlarmData[AlarmIndex].Alm_Suffix;
Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_Priority:=		Inp_AlarmData[AlarmIndex].Alm_Priority;

//Alarm acitvated (start sending)
IF Wrk_Alarm[AlarmIndex] AND NOT Wrk_AlarmSendt[AlarmIndex] THEN
	Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_AlarmState:=1;
	Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_TimeToNextPri:=TIME#0s;
	Wrk_AlarmSendt[AlarmIndex]:=TRUE;
	Wrk_AlarmReturnSendt[AlarmIndex]:=FALSE;
//Alarm acknowlegdement (stop SMS send)
ELSIF Wrk_Alarm[AlarmIndex] AND Ext_Alarm.AlarmState[AlarmIndex].Acknowledge THEN
	Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_AlarmState:=10;
	Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_TimeToNextPri:=TIME#0s;
//Alarm return (stop sending)	
ELSIF NOT Wrk_Alarm[AlarmIndex] THEN
	Wrk_AlarmSendt[AlarmIndex]:=FALSE;
	IF Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_AlarmState > 1 THEN //Does not return before SMS is sendt
		Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_AlarmState:=0;
	END_IF;
	//Send return message
	IF Ext_Alarm.Cfg_SMS_ReturnNotification AND NOT Wrk_AlarmReturnSendt[AlarmIndex] THEN 
		 IF Ext_Alarm.Cfg_OnOff AND NOT Ext_Alarm.Sts_Suppressed THEN//Will not send "return message" if alarm is turned off or supressed
			 Wrk_AlarmReturnSendt[AlarmIndex]:=TRUE;
			 Int_Alarm[AlarmToken].Sts_AlarmData[AlarmIndex].SMS_ReturnMessage:=TRUE;
		 ELSE
			 Wrk_AlarmReturnSendt[AlarmIndex]:=TRUE;
		 END_IF;
	ELSIF NOT Ext_Alarm.Cfg_SMS_ReturnNotification THEN
		Wrk_AlarmReturnSendt[AlarmIndex]:=TRUE;
	END_IF;
END_IF;

(*************************************************************************
 *	RETRIVE DATA
 *************************************************************************)
 
Wrk_AlarmTriggered:=			FALSE;

FOR Index:=0 TO DINT_TO_INT(UPPER_BOUND(Inp_AlarmData,1)) DO
		
		IF Wrk_Alarm[Index] THEN
			Wrk_AlarmTriggered:=TRUE;
		END_IF;
		
END_FOR;

(*************************************************************************
 *	DATA OUTPUT
 *************************************************************************)

//DATA TO SCADA STRUCTURE
//------------------------------------
Ext_Alarm.AlarmState[AlarmIndex].Acknowledge:=FALSE;
Ext_Alarm.AlarmState[AlarmIndex].State:=Wrk_Alarm[AlarmIndex];

//UPDATING BLOCK OUTPUT
//-----------------------------------
Out_AlarmToken:=INT_TO_UINT(AlarmToken);
Out_AlarmTriggered:= Wrk_AlarmTriggered;
